using System;
using System.Linq.Expressions;
using Nextended.Core.Enums;

namespace Nextended.Core.CodeGen;

/// <summary>
/// Fluent configuration of the DTO of one type, like a <c>ResponseFilter&lt;T&gt;</c>: derive from it and configure in the constructor.
/// The type gets a DTO also without [AutoGenerateDto]; these settings win over its attributes.
/// <para>Read by the source generator, never executed (see <see cref="CodeGenConfig"/>).</para>
/// </summary>
/// <typeparam name="T">The source type (class, record or enum).</typeparam>
public abstract class DtoConfig<T> : IDtoBuilder<T>
{
#pragma warning disable CS1591 // documented on the interfaces
    public IDtoBuilder<T> Namespace(string? value) => this;
    public IDtoBuilder<T> Usings(params string[] value) => this;
    public IDtoBuilder<T> Prefix(string? value) => this;
    public IDtoBuilder<T> Suffix(string? value) => this;
    public IDtoBuilder<T> GeneratedClassName(string? value) => this;
    public IDtoBuilder<T> GenerateMapping(bool value = true) => this;
    public IDtoBuilder<T> GenerateBeforeAndAfterAssignPartialsInMapping(bool value = true) => this;
    public IDtoBuilder<T> MappingStrategy(DtoMappingStrategy value) => this;
    public IDtoBuilder<T> ToDtoMethodName(string? value) => this;
    public IDtoBuilder<T> ToSourceMethodName(string? value) => this;
    public IDtoBuilder<T> IsComCompatible(bool value = true) => this;
    public IDtoBuilder<T> BaseType(string? value) => this;
    public IDtoBuilder<T> Interfaces(params string[] value) => this;
    public IDtoBuilder<T> ClassModifier(Modifier value) => this;
    public IDtoBuilder<T> InterfaceModifier(Modifier value) => this;
    public IDtoBuilder<T> DefaultPropertyInterfaceAccess(InterfaceProperty value) => this;
    public IDtoBuilder<T> AddReferencedNamespacesUsings(bool value = true) => this;
    public IDtoBuilder<T> AddContainingNamespaceUsings(bool value = true) => this;
    public IDtoBuilder<T> PreInterfaceString(string? value) => this;
    public IDtoBuilder<T> PreClassString(string? value) => this;
    public IDtoBuilder<T> KeepAttributesOnGeneratedClass(bool value = true) => this;
    public IDtoBuilder<T> KeepPropertyAttributesOnGeneratedInterface(bool value = true) => this;
    public IDtoBuilder<T> KeepPropertyAttributesOnGeneratedClass(bool value = true) => this;
    public IDtoBuilder<T> KeepAttributesOnGeneratedInterface(bool value = true) => this;
    public IDtoBuilder<T> AutoGenerateDerived(bool value = true) => this;
    public IDtoBuilder<T> UseViews(params string[] value) => this;
    public IDtoBuilder<T> OutputPath(string? value) => this;
    public IDtoBuilder<T> Attribute(string attribute) => this;
    public IDtoBuilder<T> Attributes(params string[] attributes) => this;
    public IDtoBuilder<T> KeepAttributes(bool value = true) => this;
    public IDtoBuilder<T> Ignore(params string[] memberNames) => this;
    public IDtoBuilder<T> Include(params string[] memberNames) => this;
    public IPropertyBuilder Property(string memberName) => null!;
    public IDtoBuilder<T> Property(string memberName, Action<IPropertyBuilder> configure) => this;
    public IDtoBuilder<T> Order(params string[] memberNames) => this;
    public IDtoBuilder<T> OrderLast(params string[] memberNames) => this;
    public IDtoBuilder<T> BaseMembersFirst(bool value = true) => this;
    public IDtoBuilder<T> Emit(string fileName, string template, string? outputPath = null) => this;
    public IDtoBuilder<T> Ignore(params Expression<Func<T, object?>>[] members) => this;
    public IDtoBuilder<T> Include(params Expression<Func<T, object?>>[] members) => this;
    public IPropertyBuilder Property<TProperty>(Expression<Func<T, TProperty>> member) => null!;
    public IDtoBuilder<T> Property<TProperty>(Expression<Func<T, TProperty>> member, Action<IPropertyBuilder> configure) => this;
    public IDtoBuilder<T> Order(params Expression<Func<T, object?>>[] members) => this;
    public IDtoBuilder<T> OrderLast(params Expression<Func<T, object?>>[] members) => this;
    public IDtoBuilder<T> Facet<TProperty>(Expression<Func<T, TProperty>> member, Action<IFacetBuilder>? configure = null) => this;
    public IDtoBuilder<T> View(string name, Action<IDtoViewBuilder<T>>? configure = null) => this;
    public IDtoBuilder<T> Typescript(Action<ITypescriptType<T>> configure) => this;
#pragma warning restore CS1591
}

/// <summary>
/// The settings of one DTO, named exactly like the properties of [AutoGenerateDto] (see there), plus member rules by name and <see cref="Emit"/>.
/// </summary>
/// <typeparam name="TSelf">The builder type, for chaining.</typeparam>
public interface IDtoSettings<out TSelf>
{
#pragma warning disable CS1591 // named exactly like the AutoGenerateDtoAttribute properties documented there
    TSelf Namespace(string? value);
    TSelf Usings(params string[] value);
    TSelf Prefix(string? value);
    TSelf Suffix(string? value);
    TSelf GeneratedClassName(string? value);
    TSelf GenerateMapping(bool value = true);
    TSelf GenerateBeforeAndAfterAssignPartialsInMapping(bool value = true);
    TSelf MappingStrategy(DtoMappingStrategy value);
    TSelf ToDtoMethodName(string? value);
    TSelf ToSourceMethodName(string? value);
    TSelf IsComCompatible(bool value = true);
    TSelf BaseType(string? value);
    TSelf Interfaces(params string[] value);
    TSelf ClassModifier(Modifier value);
    TSelf InterfaceModifier(Modifier value);
    TSelf DefaultPropertyInterfaceAccess(InterfaceProperty value);
    TSelf AddReferencedNamespacesUsings(bool value = true);
    TSelf AddContainingNamespaceUsings(bool value = true);
    TSelf PreInterfaceString(string? value);
    TSelf PreClassString(string? value);
    TSelf KeepAttributesOnGeneratedClass(bool value = true);
    TSelf KeepPropertyAttributesOnGeneratedInterface(bool value = true);
    TSelf KeepPropertyAttributesOnGeneratedClass(bool value = true);
    TSelf KeepAttributesOnGeneratedInterface(bool value = true);
    TSelf AutoGenerateDerived(bool value = true);
    TSelf UseViews(params string[] value);
    TSelf OutputPath(string? value);
#pragma warning restore CS1591

    /// <summary>Alias of <see cref="PreClassString"/>: an attribute (or any text) above the generated class.</summary>
    TSelf Attribute(string attribute);

    /// <summary>Alias of <see cref="PreClassString"/> for several attributes, e.g. <c>Attributes("[A]", "[B]")</c>.</summary>
    TSelf Attributes(params string[] attributes);

    /// <summary>Alias of <see cref="KeepAttributesOnGeneratedClass"/>.</summary>
    TSelf KeepAttributes(bool value = true);

    /// <summary>Leaves members out of this DTO, by name (also enum members). Wins over the attributes.</summary>
    TSelf Ignore(params string[] memberNames);

    /// <summary>Takes members in again that [IgnoreOnGeneration] or PropertiesToIgnore leave out, by name.</summary>
    TSelf Include(params string[] memberNames);

    /// <summary>The settings of one member, by name.</summary>
    IPropertyBuilder Property(string memberName);

    /// <summary>The settings of one member, by name; returns this builder for further calls.</summary>
    TSelf Property(string memberName, Action<IPropertyBuilder> configure);

    /// <summary>These members first, in this order; the others follow in their usual order.</summary>
    TSelf Order(params string[] memberNames);

    /// <summary>These members last, in this order (after the members of <see cref="Order(string[])"/> and all others).</summary>
    TSelf OrderLast(params string[] memberNames);

    /// <summary>Inherited members before the own ones (flat DTOs: views and DeepProperties). Combines with <see cref="Order(string[])"/>.</summary>
    TSelf BaseMembersFirst(bool value = true);

    /// <summary>
    /// Writes one more file for this DTO from a template. Placeholders in <paramref name="fileName"/> and <paramref name="template"/>:
    /// {Dto}, {Interface}, {DtoNamespace}, {DtoFullName}, {Source}, {SourceNamespace}, {SourceFullName}, {View}.
    /// The file goes where the DTO goes unless <paramref name="outputPath"/> is set; a file that is not .cs needs a path on disk.
    /// </summary>
    TSelf Emit(string fileName, string template, string? outputPath = null);
}

/// <summary>Member rules with selectors (<c>x =&gt; x.Name</c>).</summary>
public interface IDtoMembers<T, out TSelf>
{
    /// <summary>Leaves members out of this DTO. Wins over the attributes.</summary>
    TSelf Ignore(params Expression<Func<T, object?>>[] members);

    /// <summary>Takes members in again that [IgnoreOnGeneration] or PropertiesToIgnore leave out.</summary>
    TSelf Include(params Expression<Func<T, object?>>[] members);

    /// <summary>The settings of one member.</summary>
    IPropertyBuilder Property<TProperty>(Expression<Func<T, TProperty>> member);

    /// <summary>The settings of one member; returns this builder for further calls: <c>Property(x =&gt; x.A, p =&gt; p.Name("B")).Ignore(...)</c>.</summary>
    TSelf Property<TProperty>(Expression<Func<T, TProperty>> member, Action<IPropertyBuilder> configure);

    /// <summary>These members first, in this order; the others follow in their usual order.</summary>
    TSelf Order(params Expression<Func<T, object?>>[] members);

    /// <summary>These members last, in this order (after the members of <c>Order</c> and all others).</summary>
    TSelf OrderLast(params Expression<Func<T, object?>>[] members);
}

/// <summary>A type configured without a type argument (<c>typeof</c>), all types of a namespace, or the defaults of every view.</summary>
public interface IDtoTypeBuilder : IDtoSettings<IDtoTypeBuilder>
{
    /// <summary>
    /// One more DTO of the type given by <c>typeof</c> (e.g. an open generic type), a view keyed by <paramref name="name"/>; members by name.
    /// Only on <c>Dto(typeof(...))</c>: a namespace or the view defaults cannot have views. <c>Dto&lt;Page&lt;int&gt;&gt;</c> configures the
    /// generic type definition too, with member selectors.
    /// </summary>
    IDtoTypeBuilder View(string name, Action<IDtoTypeBuilder>? configure = null);
}

/// <summary>The DTO of <typeparamref name="T"/>.</summary>
public interface IDtoBuilder<T> : IDtoSettings<IDtoBuilder<T>>, IDtoMembers<T, IDtoBuilder<T>>
{
    /// <summary>
    /// One more DTO of the type, a view, keyed by <paramref name="name"/> (its GeneratedClassName), like a further [AutoGenerateDto].
    /// Its settings and member rules apply to the view alone; member rules of the type apply to it unless it has its own.
    /// </summary>
    IDtoBuilder<T> View(string name, Action<IDtoViewBuilder<T>>? configure = null);

    /// <summary>
    /// The TypeScript of the DTOs of <typeparamref name="T"/> (its default DTO and its views, members by their DTO name) and of
    /// <typeparamref name="T"/> itself when a TypeScript generation selects it.
    /// </summary>
    IDtoBuilder<T> Typescript(Action<ITypescriptType<T>> configure);

    /// <summary>
    /// A facet of the member for <c>Nextended.Core.Facets.FacetBuilder</c>, like <c>[ProvideFacet]</c> on it, without touching the type:
    /// <c>Facet(x =&gt; x.Delivered, f =&gt; f.Label("Delivered").Type(FacetType.DateRange))</c>. Settings named like the attribute's properties;
    /// on a member with <c>[ProvideFacet]</c> they override the attribute's values. The generator writes the registration
    /// (<c>Nextended.Core.Facets.FacetRegistry</c>, called from a module initializer); a facet on a base type reaches the derived types.
    /// </summary>
    IDtoBuilder<T> Facet<TProperty>(Expression<Func<T, TProperty>> member, Action<IFacetBuilder>? configure = null);
}

/// <summary>The settings of one facet, named exactly like the properties of <c>[ProvideFacet]</c>.</summary>
public interface IFacetBuilder
{
#pragma warning disable CS1591 // named exactly like the ProvideFacetAttribute properties documented there
    IFacetBuilder Label(string? value);
    IFacetBuilder Type(Nextended.Core.Facets.FacetType value);
    IFacetBuilder MultiSelect(bool value = true);
    IFacetBuilder GroupOperator(Nextended.Core.Facets.FacetGroupOperator value);
    IFacetBuilder Order(int value);
    IFacetBuilder TopDistinct(int value);
    IFacetBuilder ValuePath(string? value);
    IFacetBuilder LabelPath(string? value);
    IFacetBuilder ValueType(Type? value);
#pragma warning restore CS1591

    /// <summary><see cref="ValueType(Type)"/> as a type argument.</summary>
    IFacetBuilder ValueType<TValue>();
}

/// <summary>A view of <typeparamref name="T"/>.</summary>
public interface IDtoViewBuilder<T> : IDtoSettings<IDtoViewBuilder<T>>, IDtoMembers<T, IDtoViewBuilder<T>>;

/// <summary>The settings of one member, named exactly like the properties of [GenerationPropertySetting].</summary>
public interface IPropertyBuilder
{
#pragma warning disable CS1591
    IPropertyBuilder PropertyName(string value);
    IPropertyBuilder MapWithClassMapper(bool value = true);
    IPropertyBuilder InterfaceAccess(InterfaceProperty value);
    IPropertyBuilder PreInterfaceString(string? value);
    IPropertyBuilder PreClassString(string? value);
    IPropertyBuilder KeepAttributesOnGeneratedClass(bool value = true);
    IPropertyBuilder KeepAttributesOnGeneratedInterface(bool value = true);
#pragma warning restore CS1591

    /// <summary>Alias of <see cref="PropertyName"/>: the member's name in the DTO.</summary>
    IPropertyBuilder Name(string value);

    /// <summary>Alias of <see cref="PreClassString"/>: an attribute (or any text) above the generated property.</summary>
    IPropertyBuilder Attribute(string attribute);

    /// <summary>Alias of <see cref="PreClassString"/> for several attributes, e.g. <c>Attributes("[A]", "[B]")</c>.</summary>
    IPropertyBuilder Attributes(params string[] attributes);

    /// <summary>Alias of <see cref="KeepAttributesOnGeneratedClass"/>.</summary>
    IPropertyBuilder KeepAttributes(bool value = true);

    /// <summary>Leaves the member out of this DTO.</summary>
    IPropertyBuilder Ignore();

    /// <summary>Takes the member in again that [IgnoreOnGeneration] or PropertiesToIgnore leave out.</summary>
    IPropertyBuilder Include();
}
